Object.assign(SNIP,{});PRESET_NOTES["l73"]={"Ví dụ: Bộ sinh số ngẫu nhiên": "Bộ sinh đồng dư tuyến tính: mỗi số mới tính từ số trước. Cùng hạt giống thì cùng dãy — chạy lại bao nhiêu lần cũng ra đúng ba mảng này, rất tiện khi cần tái hiện lỗi.", "Ví dụ: Vòng lặp đối chiếu": "Ở lần thử thứ 13, máy tìm ra mảng toàn số âm {−3, −1}: lời giải “nhanh” trả 0 (đoạn rỗng) còn trâu bò trả số âm lớn nhất. Lỗi khởi tạo của bài 72 bị bắt mà không cần nghĩ ra trường hợp đó.", "Ví dụ: Tìm phản ví dụ nhỏ nhất": "Tăng dần kích thước trước khi tăng số lần thử: phản ví dụ thu gọn còn đúng một phần tử âm — nhìn là thấy lỗi.", "Ví dụ: Thử các trường hợp biên": "Danh sách biên viết tay bổ sung cho kiểm thử ngẫu nhiên: n nhỏ nhất, toàn số bằng nhau, số âm, giá trị cực đại. Mỗi dòng ứng với một nghi ngờ cụ thể.", "Lỗi: khoảng giá trị quá rộng nên không lộ lỗi": "Báo 0 lần khác nhau dù lời giải nhanh sai: với giá trị tới 10^6, hầu như không bao giờ sinh ra ba số bằng nhau. Đổi thành ngauNhien(1, 3) là lộ lỗi ngay. Khoảng giá trị nhỏ làm trùng lặp và biên xuất hiện thường xuyên."};EX_HINTS["l73"]=[["Thử trường hợp x lớn hơn hoặc bằng mọi phần tử: đáp án phải là n. Code mẫu trả về gì?", "Vị trí đầu tiên có a[i] > x nằm trong [0, n] — n nghĩa là “không có”. Khoảng tìm kiếm phải là hi = n, không phải n − 1.", "Lời giải trâu bò để đối chiếu: đếm từng phần tử ≤ x. Đúng nhưng O(n) mỗi câu hỏi."], ["Lỗi 1 — thử {−10, −3, 1, 2}: hai số âm có trị tuyệt đối lớn cho tích 30, lớn hơn 2 · 1.", "Lỗi 2 — thử {10^9, 10^9}: tích 10^18 tràn int. Dùng long long cho cả mảng hoặc ép kiểu trước khi nhân.", "Trâu bò để đối chiếu: thử mọi cặp i < j, O(n²)."], ["Đối chiếu với trâu bò trên dữ liệu nhỏ, giá trị trong {1, 2, 3}: {7, 7, 7} có 3 cặp, code mẫu đếm 2.", "Sau khi sắp, các số bằng nhau đứng thành nhóm liền nhau. Nhóm k phần tử cho k(k − 1)/2 cặp, không phải k − 1.", "Số cặp tới n²/2 ≈ 2·10^10: long long. (Cách khác: bảng băm đếm tần suất, cộng số lần đã gặp.)"]];
/* ===================== BÀI 73 · Kiểm thử đối chiếu (stress test) và gỡ lỗi ===================== */
/* Bài 73 · Kiểm thử đối chiếu (stress test) và gỡ lỗi
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR73=[{label:"Ví dụ: Bộ sinh số ngẫu nhiên",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nlong long hat = 12345;                 // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\nint ngauNhien(int lo, int hi) {        // số giả ngẫu nhiên trong [lo, hi]\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nint main() {\n    for (int t = 0; t < 3; t++) {\n        int n = ngauNhien(1, 6);\n        cout << n << \":\";\n        for (int i = 0; i < n; i++) cout << \" \" << ngauNhien(-5, 5);\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["hat","t","n","i"]}],py:{code:"hat = 12345                            # hạt giống cố định: chạy lại ra đúng dãy số cũ\n\ndef ngau_nhien(lo, hi):                # số giả ngẫu nhiên trong [lo, hi]\n    global hat\n    hat = (hat * 1103515245 + 12345) % 2147483648\n    return lo + hat // 65536 % (hi - lo + 1)\n\nfor t in range(3):\n    n = ngau_nhien(1, 6)\n    a = [ngau_nhien(-5, 5) for _ in range(n)]\n    print(str(n) + \":\", *a)",note:"Bộ sinh đồng dư tuyến tính: mỗi số mới tính từ số trước. Cùng hạt giống thì cùng dãy — chạy lại bao nhiêu lần cũng ra đúng ba mảng này. (Thư viện random với random.seed(…) cố định cũng cho kết quả lặp lại được.)"},cs:{code:"using System;\n\nclass Program\n{\n    static long hat = 12345;               // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\n    static int NgauNhien(int lo, int hi)   // số giả ngẫu nhiên trong [lo, hi]\n    {\n        hat = (hat * 1103515245 + 12345) % 2147483648L;\n        return lo + (int)(hat / 65536 % (hi - lo + 1));\n    }\n\n    static void Main()\n    {\n        for (int t = 0; t < 3; t++)\n        {\n            int n = NgauNhien(1, 6);\n            Console.Write(n + \":\");\n            for (int i = 0; i < n; i++) Console.Write(\" \" + NgauNhien(-5, 5));\n            Console.WriteLine();\n        }\n    }\n}"}},{label:"Ví dụ: Vòng lặp đối chiếu",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nlong long hat = 12345;                 // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\nint ngauNhien(int lo, int hi) {        // số giả ngẫu nhiên trong [lo, hi]\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nlong long trauBo(const vector<long long>& a) {   // chắc chắn đúng: thử mọi đoạn\n    long long tot = a[0];\n    for (int i = 0; i < (int)a.size(); i++) {\n        long long s = 0;\n        for (int j = i; j < (int)a.size(); j++) { s += a[j]; tot = max(tot, s); }\n    }\n    return tot;\n}\n\nlong long nhanh(const vector<long long>& a) {    // lời giải cần kiểm tra\n    long long ketThuc = 0, tot = 0;    // (có lỗi ẩn)\n    for (long long x : a) {\n        ketThuc = max(x, ketThuc + x);\n        tot = max(tot, ketThuc);\n    }\n    return tot;\n}\n\nint main() {\n    for (int lan = 1; lan <= 1000; lan++) {\n        int n = ngauNhien(1, 5);\n        vector<long long> a(n);\n        for (auto& x : a) x = ngauNhien(-5, 5);\n        long long p = nhanh(a), q = trauBo(a);\n        if (p != q) {                  // tìm thấy phản ví dụ\n            cout << \"lan \" << lan << \": n = \" << n << \", a =\";\n            for (long long x : a) cout << \" \" << x;\n            cout << \"\\nnhanh = \" << p << \", trau bo = \" << q << \"\\n\";\n            return 0;\n        }\n    }\n    cout << \"khong tim thay khac biet\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["lan","n","p","q"]}],py:{code:"hat = 12345                            # hạt giống cố định: chạy lại ra đúng dãy số cũ\n\ndef ngau_nhien(lo, hi):                # số giả ngẫu nhiên trong [lo, hi]\n    global hat\n    hat = (hat * 1103515245 + 12345) % 2147483648\n    return lo + hat // 65536 % (hi - lo + 1)\n\ndef trau_bo(a):                        # chắc chắn đúng: thử mọi đoạn\n    tot = a[0]\n    for i in range(len(a)):\n        s = 0\n        for j in range(i, len(a)):\n            s += a[j]\n            tot = max(tot, s)\n    return tot\n\ndef nhanh(a):                          # lời giải cần kiểm tra (có lỗi ẩn)\n    ket_thuc = tot = 0\n    for x in a:\n        ket_thuc = max(x, ket_thuc + x)\n        tot = max(tot, ket_thuc)\n    return tot\n\nfor lan in range(1, 1001):\n    n = ngau_nhien(1, 5)\n    a = [ngau_nhien(-5, 5) for _ in range(n)]\n    p, q = nhanh(a), trau_bo(a)\n    if p != q:                         # tìm thấy phản ví dụ\n        print(\"lan \" + str(lan) + \": n = \" + str(n) + \", a =\", *a)\n        print(\"nhanh = \" + str(p) + \", trau bo = \" + str(q))\n        break\nelse:\n    print(\"khong tim thay khac biet\")"},cs:{code:"using System;\n\nclass Program\n{\n    static long hat = 12345;               // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\n    static int NgauNhien(int lo, int hi)   // số giả ngẫu nhiên trong [lo, hi]\n    {\n        hat = (hat * 1103515245 + 12345) % 2147483648L;\n        return lo + (int)(hat / 65536 % (hi - lo + 1));\n    }\n\n    static long TrauBo(long[] a)           // chắc chắn đúng: thử mọi đoạn\n    {\n        long tot = a[0];\n        for (int i = 0; i < a.Length; i++)\n        {\n            long s = 0;\n            for (int j = i; j < a.Length; j++) { s += a[j]; tot = Math.Max(tot, s); }\n        }\n        return tot;\n    }\n\n    static long Nhanh(long[] a)            // lời giải cần kiểm tra (có lỗi ẩn)\n    {\n        long ketThuc = 0, tot = 0;\n        foreach (long x in a)\n        {\n            ketThuc = Math.Max(x, ketThuc + x);\n            tot = Math.Max(tot, ketThuc);\n        }\n        return tot;\n    }\n\n    static void Main()\n    {\n        for (int lan = 1; lan <= 1000; lan++)\n        {\n            int n = NgauNhien(1, 5);\n            long[] a = new long[n];\n            for (int i = 0; i < n; i++) a[i] = NgauNhien(-5, 5);\n            long p = Nhanh(a), q = TrauBo(a);\n            if (p != q)                        // tìm thấy phản ví dụ\n            {\n                Console.Write(\"lan \" + lan + \": n = \" + n + \", a =\");\n                foreach (long x in a) Console.Write(\" \" + x);\n                Console.WriteLine();\n                Console.WriteLine(\"nhanh = \" + p + \", trau bo = \" + q);\n                return;\n            }\n        }\n        Console.WriteLine(\"khong tim thay khac biet\");\n    }\n}"}},{label:"Ví dụ: Tìm phản ví dụ nhỏ nhất",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nlong long hat = 12345;                 // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\nint ngauNhien(int lo, int hi) {        // số giả ngẫu nhiên trong [lo, hi]\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nlong long trauBo(const vector<long long>& a) {   // chắc chắn đúng: thử mọi đoạn\n    long long tot = a[0];\n    for (int i = 0; i < (int)a.size(); i++) {\n        long long s = 0;\n        for (int j = i; j < (int)a.size(); j++) { s += a[j]; tot = max(tot, s); }\n    }\n    return tot;\n}\n\nlong long nhanh(const vector<long long>& a) {    // lời giải cần kiểm tra\n    long long ketThuc = 0, tot = 0;    // (có lỗi ẩn)\n    for (long long x : a) {\n        ketThuc = max(x, ketThuc + x);\n        tot = max(tot, ketThuc);\n    }\n    return tot;\n}\n\nint main() {\n    for (int n = 1; n <= 5; n++)       // thử n tăng dần: phản ví dụ đầu tiên là nhỏ nhất\n        for (int lan = 0; lan < 200; lan++) {\n            vector<long long> a(n);\n            for (auto& x : a) x = ngauNhien(-3, 3);\n            if (nhanh(a) != trauBo(a)) {\n                cout << \"n = \" << n << \", a =\";\n                for (long long x : a) cout << \" \" << x;\n                cout << \": nhanh \" << nhanh(a) << \", trau bo \" << trauBo(a) << \"\\n\";\n                return 0;\n            }\n        }\n    cout << \"khong tim thay khac biet\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["n","lan"]}],py:{code:"hat = 12345                            # hạt giống cố định: chạy lại ra đúng dãy số cũ\n\ndef ngau_nhien(lo, hi):                # số giả ngẫu nhiên trong [lo, hi]\n    global hat\n    hat = (hat * 1103515245 + 12345) % 2147483648\n    return lo + hat // 65536 % (hi - lo + 1)\n\ndef trau_bo(a):                        # chắc chắn đúng: thử mọi đoạn\n    tot = a[0]\n    for i in range(len(a)):\n        s = 0\n        for j in range(i, len(a)):\n            s += a[j]\n            tot = max(tot, s)\n    return tot\n\ndef nhanh(a):                          # lời giải cần kiểm tra (có lỗi ẩn)\n    ket_thuc = tot = 0\n    for x in a:\n        ket_thuc = max(x, ket_thuc + x)\n        tot = max(tot, ket_thuc)\n    return tot\n\ndef tim():\n    for n in range(1, 6):              # thử n tăng dần: phản ví dụ đầu tiên là nhỏ nhất\n        for lan in range(200):\n            a = [ngau_nhien(-3, 3) for _ in range(n)]\n            if nhanh(a) != trau_bo(a):\n                print(\"n = \" + str(n) + \", a =\", *a, end=\"\")\n                print(\": nhanh \" + str(nhanh(a)) + \", trau bo \" + str(trau_bo(a)))\n                return\n    print(\"khong tim thay khac biet\")\n\ntim()"},cs:{code:"using System;\n\nclass Program\n{\n    static long hat = 12345;               // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\n    static int NgauNhien(int lo, int hi)   // số giả ngẫu nhiên trong [lo, hi]\n    {\n        hat = (hat * 1103515245 + 12345) % 2147483648L;\n        return lo + (int)(hat / 65536 % (hi - lo + 1));\n    }\n\n    static long TrauBo(long[] a)           // chắc chắn đúng: thử mọi đoạn\n    {\n        long tot = a[0];\n        for (int i = 0; i < a.Length; i++)\n        {\n            long s = 0;\n            for (int j = i; j < a.Length; j++) { s += a[j]; tot = Math.Max(tot, s); }\n        }\n        return tot;\n    }\n\n    static long Nhanh(long[] a)            // lời giải cần kiểm tra (có lỗi ẩn)\n    {\n        long ketThuc = 0, tot = 0;\n        foreach (long x in a)\n        {\n            ketThuc = Math.Max(x, ketThuc + x);\n            tot = Math.Max(tot, ketThuc);\n        }\n        return tot;\n    }\n\n    static void Main()\n    {\n        for (int n = 1; n <= 5; n++)           // thử n tăng dần: phản ví dụ đầu tiên là nhỏ nhất\n            for (int lan = 0; lan < 200; lan++)\n            {\n                long[] a = new long[n];\n                for (int i = 0; i < n; i++) a[i] = NgauNhien(-3, 3);\n                if (Nhanh(a) != TrauBo(a))\n                {\n                    Console.Write(\"n = \" + n + \", a =\");\n                    foreach (long x in a) Console.Write(\" \" + x);\n                    Console.WriteLine(\": nhanh \" + Nhanh(a) + \", trau bo \" + TrauBo(a));\n                    return;\n                }\n            }\n        Console.WriteLine(\"khong tim thay khac biet\");\n    }\n}"}},{label:"Ví dụ: Thử các trường hợp biên",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nlong long tichLonNhat(vector<long long> a) {   // tích lớn nhất của hai phần tử khác vị trí\n    sort(a.begin(), a.end());\n    int n = a.size();\n    return max(a[0] * a[1], a[n - 1] * a[n - 2]);   // hai số nhỏ nhất (có thể cùng âm) hoặc hai số lớn nhất\n}\n\nint main() {\n    vector<vector<long long>> bien = {\n        {1, 2},                        // n nhỏ nhất\n        {-10, -3, 1, 2},               // hai số âm cho tích dương lớn\n        {5, 5, 5},                     // mọi phần tử bằng nhau\n        {1000000000, 1000000000},      // tích 10^18: cần long long\n        {-1, 0, 1}};\n    for (auto& a : bien) cout << tichLonNhat(a) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"}],py:{code:"def tich_lon_nhat(a):                  # tích lớn nhất của hai phần tử khác vị trí\n    a = sorted(a)\n    return max(a[0] * a[1], a[-1] * a[-2])   # hai số nhỏ nhất (có thể cùng âm) hoặc hai số lớn nhất\n\nbien = [\n    [1, 2],                            # n nhỏ nhất\n    [-10, -3, 1, 2],                   # hai số âm cho tích dương lớn\n    [5, 5, 5],                         # mọi phần tử bằng nhau\n    [1000000000, 1000000000],          # tích 10^18\n    [-1, 0, 1]]\nfor a in bien:\n    print(tich_lon_nhat(a))",note:"Danh sách biên viết tay bổ sung cho kiểm thử ngẫu nhiên: n nhỏ nhất, toàn số bằng nhau, số âm, giá trị cực đại. Python không tràn số, nhưng khi chuyển lời giải sang C++/C# thì dòng thứ tư nhắc phải dùng kiểu 64 bit."},cs:{code:"using System;\n\nclass Program\n{\n    static long TichLonNhat(long[] goc)    // tích lớn nhất của hai phần tử khác vị trí\n    {\n        long[] a = (long[])goc.Clone();\n        Array.Sort(a);\n        int n = a.Length;\n        return Math.Max(a[0] * a[1], a[n - 1] * a[n - 2]);   // hai số nhỏ nhất (có thể cùng âm) hoặc hai số lớn nhất\n    }\n\n    static void Main()\n    {\n        long[][] bien = {\n            new long[] { 1, 2 },               // n nhỏ nhất\n            new long[] { -10, -3, 1, 2 },      // hai số âm cho tích dương lớn\n            new long[] { 5, 5, 5 },            // mọi phần tử bằng nhau\n            new long[] { 1000000000, 1000000000 },   // tích 10^18: cần long\n            new long[] { -1, 0, 1 } };\n        foreach (long[] a in bien) Console.WriteLine(TichLonNhat(a));\n    }\n}"}},{label:"Lỗi: khoảng giá trị quá rộng nên không lộ lỗi",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nlong long hat = 12345;                 // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\nint ngauNhien(int lo, int hi) {        // số giả ngẫu nhiên trong [lo, hi]\n    hat = (hat * 1103515245 + 12345) % 2147483648LL;\n    return lo + (int)(hat / 65536 % (hi - lo + 1));\n}\n\nlong long trauBo(const vector<int>& a) {         // đếm cặp i < j có a[i] = a[j]\n    long long d = 0;\n    for (int i = 0; i < (int)a.size(); i++)\n        for (int j = i + 1; j < (int)a.size(); j++)\n            if (a[i] == a[j]) d++;\n    return d;\n}\n\nlong long nhanh(vector<int> a) {       // sai khi có từ 3 số bằng nhau trở lên\n    sort(a.begin(), a.end());\n    long long d = 0;\n    for (int i = 0; i + 1 < (int)a.size(); i++)\n        if (a[i] == a[i + 1]) d++;     // chỉ đếm cặp kề nhau sau khi sắp\n    return d;\n}\n\nint main() {\n    int saiKhac = 0;\n    for (int lan = 0; lan < 200; lan++) {\n        int n = ngauNhien(1, 6);\n        vector<int> a(n);\n        for (auto& x : a) x = ngauNhien(1, 1000000);   // SAI: giá trị gần như không bao giờ trùng\n        if (nhanh(a) != trauBo(a)) saiKhac++;\n    }\n    cout << saiKhac << \" lan khac nhau\\n\";           // tưởng đúng, nhưng {7, 7, 7}: nhanh 2, trau bo 3\n    return 0;\n}",viz:[{type:"vars",names:["lan","n","saiKhac"]}],py:{code:"hat = 12345                            # hạt giống cố định: chạy lại ra đúng dãy số cũ\n\ndef ngau_nhien(lo, hi):                # số giả ngẫu nhiên trong [lo, hi]\n    global hat\n    hat = (hat * 1103515245 + 12345) % 2147483648\n    return lo + hat // 65536 % (hi - lo + 1)\n\ndef trau_bo(a):                        # đếm cặp i < j có a[i] = a[j]\n    return sum(1 for i in range(len(a)) for j in range(i + 1, len(a)) if a[i] == a[j])\n\ndef nhanh(a):                          # sai khi có từ 3 số bằng nhau trở lên\n    a = sorted(a)\n    return sum(1 for i in range(len(a) - 1) if a[i] == a[i + 1])   # chỉ đếm cặp kề nhau\n\nsai_khac = 0\nfor lan in range(200):\n    n = ngau_nhien(1, 6)\n    a = [ngau_nhien(1, 1000000) for _ in range(n)]   # SAI: giá trị gần như không bao giờ trùng\n    if nhanh(a) != trau_bo(a):\n        sai_khac += 1\nprint(sai_khac, \"lan khac nhau\")       # tưởng đúng, nhưng [7, 7, 7]: nhanh 2, trau bo 3"},cs:{code:"using System;\n\nclass Program\n{\n    static long hat = 12345;               // hạt giống cố định: chạy lại ra đúng dãy số cũ\n\n    static int NgauNhien(int lo, int hi)   // số giả ngẫu nhiên trong [lo, hi]\n    {\n        hat = (hat * 1103515245 + 12345) % 2147483648L;\n        return lo + (int)(hat / 65536 % (hi - lo + 1));\n    }\n\n    static long TrauBo(int[] a)            // đếm cặp i < j có a[i] = a[j]\n    {\n        long d = 0;\n        for (int i = 0; i < a.Length; i++)\n            for (int j = i + 1; j < a.Length; j++)\n                if (a[i] == a[j]) d++;\n        return d;\n    }\n\n    static long Nhanh(int[] goc)           // sai khi có từ 3 số bằng nhau trở lên\n    {\n        int[] a = (int[])goc.Clone();\n        Array.Sort(a);\n        long d = 0;\n        for (int i = 0; i + 1 < a.Length; i++)\n            if (a[i] == a[i + 1]) d++;     // chỉ đếm cặp kề nhau sau khi sắp\n        return d;\n    }\n\n    static void Main()\n    {\n        int saiKhac = 0;\n        for (int lan = 0; lan < 200; lan++)\n        {\n            int n = NgauNhien(1, 6);\n            int[] a = new int[n];\n            for (int i = 0; i < n; i++) a[i] = NgauNhien(1, 1000000);   // SAI: giá trị gần như không bao giờ trùng\n            if (Nhanh(a) != TrauBo(a)) saiKhac++;\n        }\n        Console.WriteLine(saiKhac + \" lan khac nhau\");   // tưởng đúng, nhưng {7, 7, 7}: nhanh 2, trau bo 3\n    }\n}"}}];
