makeEx2(document.getElementById("ex-l73"),sim73,[{t:"Sửa lỗi: đếm số không vượt quá",d:"Mảng a_1 ≤ a_2 ≤ … ≤ a_n đã sắp tăng dần. Mỗi câu hỏi x: có bao nhiêu phần tử ≤ x? Đầu vào: n q (1 ≤ n, q ≤ 2·10^5) rồi dòng a đã sắp (|a_i| ≤ 10^9), rồi q dòng x. Đầu ra: q dòng. Code mẫu dùng tìm kiếm nhị phân nhưng có lỗi — hãy dùng kiểm thử đối chiếu (hoặc thử tay các trường hợp biên) để tìm và sửa.",tests:[{in:"5 5\n1 3 3 5 8\n3\n0\n8\n9\n4",out:"3\n0\n5\n5\n3"},{in:"1 3\n5\n4\n5\n6",out:"0\n1\n1"},{in:"3 3\n2 2 2\n2\n1\n3",out:"3\n0\n3"},{in:"2 3\n-1000000000 1000000000\n1000000000\n-1000000000\n0",out:"2\n1\n1"},{in:"40 40\n-19 -19 -17 -16 -15 -13 -13 -12 -9 -9 -8 -8 -6 -4 -4 -3 -2 -1 2 2 5 6 6 7 7 8 9 9 10 11 11 12 12 13 15 15 16 16 17 18\n-24\n-12\n-8\n-8\n20\n-22\n23\n-10\n7\n-15\n14\n2\n-20\n-20\n25\n18\n-20\n16\n-13\n-17\n10\n-16\n3\n4\n24\n24\n6\n20\n10\n-10\n-3\n-6\n-13\n-22\n1\n-19\n2\n0\n-22\n17",out:"0\n8\n12\n12\n40\n0\n40\n8\n25\n5\n34\n20\n0\n0\n40\n40\n0\n38\n7\n3\n29\n4\n20\n20\n40\n40\n23\n40\n29\n8\n16\n13\n7\n0\n18\n2\n20\n18\n0\n39"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    for (int k = 0; k < q; k++) {\n        long long x;\n        cin >> x;\n        int lo = 0, hi = n - 1;        // tìm vị trí đầu tiên có a[i] > x\n        while (lo < hi) {\n            int mid = (lo + hi) / 2;\n            if (a[mid] > x) hi = mid;\n            else lo = mid + 1;\n        }\n        cout << lo << \"\\n\";            // số phần tử đứng trước vị trí đó\n    }\n    return 0;\n}",perf:{gen:n=>{const a=Array.from({length:n},(_,i)=>2*i);const q=Array.from({length:n},(_,i)=>(i*7)%(2*n+3));return n+" "+n+"\n"+a.join(" ")+"\n"+q.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+300,why:"Đếm từng phần tử cho mỗi câu hỏi tốn O(n) mỗi câu."},py:{start:"n, q = map(int, input().split())\na = list(map(int, input().split()))\nout = []\nfor _ in range(q):\n    x = int(input())\n    lo, hi = 0, n - 1                  # tìm vị trí đầu tiên có a[i] > x\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] > x:\n            hi = mid\n        else:\n            lo = mid + 1\n    out.append(lo)                     # số phần tử đứng trước vị trí đó\nprint(\"\\n\".join(map(str, out)))",hints:["Thử trường hợp x lớn hơn hoặc bằng mọi phần tử: đáp án phải là n. Code mẫu trả về gì?","Vị trí đầu tiên có a[i] > x nằm trong [0, n] — n nghĩa là “không có”. Khoảng tìm kiếm phải là hi = n. (bisect.bisect_right(a, x) làm đúng việc này.)","Lời giải trâu bò để đối chiếu: sum(1 for v in a if v <= x). Đúng nhưng O(n) mỗi câu hỏi."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nq = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nq[0], q = nq[1];\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        var sb = new StringBuilder();\n        for (int k = 0; k < q; k++)\n        {\n            long x = long.Parse(Console.ReadLine());\n            int lo = 0, hi = n - 1;                 // tìm vị trí đầu tiên có a[i] > x\n            while (lo < hi)\n            {\n                int mid = (lo + hi) / 2;\n                if (a[mid] > x) hi = mid;\n                else lo = mid + 1;\n            }\n            sb.Append(lo).Append('\\n');\n        }\n        Console.Write(sb.ToString());\n    }\n}",hints:["Thử trường hợp x lớn hơn hoặc bằng mọi phần tử: đáp án phải là n. Code mẫu trả về gì?","Vị trí đầu tiên có a[i] > x nằm trong [0, n] — n nghĩa là “không có”. Khoảng tìm kiếm phải là hi = n.","Lời giải trâu bò để đối chiếu: đếm từng phần tử ≤ x. Đúng nhưng O(n) mỗi câu hỏi."]}},{t:"Sửa lỗi: tích lớn nhất",d:"Cho n số nguyên (2 ≤ n ≤ 2·10^5, |a_i| ≤ 10^9). Chọn hai phần tử ở hai vị trí khác nhau để tích lớn nhất; in tích đó. Code mẫu có hai lỗi — hãy tìm bằng các trường hợp biên: số âm, số lớn.",tests:[{in:"5\n3 1 4 1 5",out:"20"},{in:"4\n-10 -3 1 2",out:"30"},{in:"3\n1000000000 1000000000 -1",out:"1000000000000000000"},{in:"3\n-1000000000 -1000000000 5",out:"1000000000000000000"},{in:"2\n-1 0",out:"0"},{in:"3\n5 5 5",out:"25"},{in:"40\n543916972 -807182101 -223227329 -118417416 -640018176 -263075927 673599129 50829692 -800826454 -706831606 -483330670 984306695 -734764901 745100823 177331071 -355050754 837564410 -171113021 -114701685 -443974202 529421529 -124780659 -826004345 49170055 -928082205 608984145 649610106 -795024771 -775205932 360551911 927079677 -438085937 149005234 2571330 175957358 -805812903 376458108 -530680868 -304900671 -903351878",out:"912530732869537515"},{in:"30\n-2 -4 -5 -1 -2 -3 1 -5 5 4 4 1 4 5 5 5 -3 -5 -2 -3 3 -2 5 1 -3 1 -4 -4 4 1",out:"25"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (auto& x : a) cin >> x;\n    sort(a.begin(), a.end());\n    int tich = a[n - 1] * a[n - 2];    // hai số lớn nhất\n    cout << tich << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\na = sorted(map(int, input().split()))\nprint(a[-1] * a[-2])                   # hai số lớn nhất",hints:["Thử {−10, −3, 1, 2}: hai số âm có trị tuyệt đối lớn cho tích 30, lớn hơn 2 · 1.","Đáp án là max của tích hai số lớn nhất và tích hai số nhỏ nhất.","Python không tràn số nên chỉ có một lỗi; bản C++/C# của bài này còn lỗi tràn int."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        Array.Sort(a);\n        int tich = a[n - 1] * a[n - 2];        // hai số lớn nhất\n        Console.WriteLine(tich);\n    }\n}",hints:["Lỗi 1 — thử {−10, −3, 1, 2}: hai số âm có trị tuyệt đối lớn cho tích 30, lớn hơn 2 · 1.","Lỗi 2 — thử {10^9, 10^9}: tích 10^18 tràn int (C# không báo lỗi, chỉ quấn vòng). Dùng long.","Trâu bò để đối chiếu: thử mọi cặp i < j, O(n²)."]}},{t:"Sửa lỗi: đếm cặp trùng",d:"Đếm số cặp chỉ số i < j có a_i = a_j. Đầu vào: n (1 ≤ n ≤ 2·10^5) rồi n số (|a_i| ≤ 10^9). Đầu ra: một số. Code mẫu chính là lời giải “nhanh” trong ví dụ cuối của mô phỏng — hãy sửa nó.",tests:[{in:"3\n7 7 7",out:"3"},{in:"5\n1 2 1 2 1",out:"4"},{in:"1\n5",out:"0"},{in:"3\n1 2 3",out:"0"},{in:"10\n4 4 4 4 4 4 4 4 4 4",out:"45"},{in:"30\n2 3 2 2 1 2 2 2 1 2 2 2 2 1 2 2 2 3 3 3 1 2 2 3 1 1 3 3 2 3",out:"163"},{in:"30\n703579355 539397600 357840535 -195830015 114469480 -819654547 344605598 -313910798 823849151 131248115 930736389 -170516565 500261409 -26008280 -1821408 -113683276 659959890 -998224739 -901334853 -568815305 567515742 235442570 348793089 -739499827 -892089372 -203999796 -542331048 739269053 -398038490 38890066",out:"0"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    sort(a.begin(), a.end());\n    long long d = 0;\n    for (int i = 0; i + 1 < n; i++)\n        if (a[i] == a[i + 1]) d++;     // chỉ đếm cặp kề nhau sau khi sắp\n    cout << d << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>i%5).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+300,why:"Thử mọi cặp tốn O(n²)."},py:{start:"n = int(input())\na = sorted(map(int, input().split()))\nd = 0\nfor i in range(n - 1):\n    if a[i] == a[i + 1]:               # chỉ đếm cặp kề nhau sau khi sắp\n        d += 1\nprint(d)",hints:["Đối chiếu với trâu bò trên dữ liệu nhỏ, giá trị trong {1, 2, 3}: [7, 7, 7] có 3 cặp, code mẫu đếm 2.","Sau khi sắp, các số bằng nhau đứng thành nhóm liền nhau. Nhóm k phần tử cho k(k − 1)/2 cặp.","Cách khác: collections.Counter rồi cộng c·(c − 1)//2 cho mỗi giá trị."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        Array.Sort(a);\n        long d = 0;\n        for (int i = 0; i + 1 < n; i++)\n            if (a[i] == a[i + 1]) d++;         // chỉ đếm cặp kề nhau sau khi sắp\n        Console.WriteLine(d);\n    }\n}",hints:["Đối chiếu với trâu bò trên dữ liệu nhỏ, giá trị trong {1, 2, 3}: {7, 7, 7} có 3 cặp, code mẫu đếm 2.","Sau khi sắp, các số bằng nhau đứng thành nhóm liền nhau. Nhóm k phần tử cho k(k − 1)/2 cặp.","Số cặp tới 2·10^10: long. (Cách khác: Dictionary đếm tần suất.)"]}}]);

